-- ============================================================================
-- Migration 078 — Referral Engine (Contract 1 of 4: referral-engine)
-- ----------------------------------------------------------------------------
-- Backend foundation for the marketing referral system: a referrer (a partner
-- AGENCY or an INFLUENCER) earns an admin-set % of the PLATFORM's own revenue
-- generated by an entity they referred (a BRAND or an INFLUENCER), for 12
-- months from the referral. Carved from the platform's slice ONLY — never
-- reduces influencer earnings, escrow net_to_influencer, or brand net.
--
-- Additive + idempotent + forward-only (per migration convention). No
-- destructive change: three new tables, one partial unique index, one
-- nullable-with-default column. DORMANT on deploy — with zero referral_edges
-- rows in prod the engine never accrues; it activates only once Contracts 2/3
-- create edges.
-- ============================================================================

BEGIN;

-- ── 1. referral_codes — a referrer's shareable code ────────────────────────
CREATE TABLE IF NOT EXISTS referral_codes (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  referrer_type text NOT NULL CHECK (referrer_type IN ('agency','influencer')),
  referrer_id   uuid NOT NULL,
  code          text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now()
);

-- one code per referrer, and codes are globally unique
CREATE UNIQUE INDEX IF NOT EXISTS uniq_referral_code
  ON referral_codes (code);
CREATE UNIQUE INDEX IF NOT EXISTS uniq_referral_code_owner
  ON referral_codes (referrer_type, referrer_id);

-- ── 2. referral_edges — the locked referral relationship ───────────────────
CREATE TABLE IF NOT EXISTS referral_edges (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  referrer_type       text NOT NULL CHECK (referrer_type IN ('agency','influencer')),
  referrer_id         uuid NOT NULL,
  referred_type       text NOT NULL CHECK (referred_type IN ('brand','influencer')),
  referred_id         uuid NOT NULL,
  pct                 numeric(5,2) NOT NULL,
  kind                text NOT NULL DEFAULT 'referral' CHECK (kind IN ('referral','managed')),
  status              text NOT NULL DEFAULT 'active'   CHECK (status IN ('active','expired','ended')),
  source              text NOT NULL                    CHECK (source IN ('signup','admin')),
  code_id             uuid NULL REFERENCES referral_codes(id),
  created_by_admin_id uuid NULL,
  started_at          timestamptz NOT NULL DEFAULT now(),
  expires_at          timestamptz NOT NULL,
  ended_at            timestamptz NULL,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now()
);

-- THE dedup guarantee: at most one ACTIVE referrer per referred entity
-- (first-touch, locked). Partial unique index — expired/ended edges don't block.
CREATE UNIQUE INDEX IF NOT EXISTS uniq_referral_active_referred
  ON referral_edges (referred_type, referred_id)
  WHERE status = 'active';

-- fast resolve path: "give me the active edge for this referred entity"
CREATE INDEX IF NOT EXISTS idx_referral_edges_referred
  ON referral_edges (referred_type, referred_id, status);

-- ── 3. referral_ledger — one row per accrued revenue event (source of truth)─
CREATE TABLE IF NOT EXISTS referral_ledger (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  edge_id       uuid NOT NULL REFERENCES referral_edges(id),
  referrer_type text NOT NULL,           -- denormalized for fast reporting
  referrer_id   uuid NOT NULL,
  source        text NOT NULL CHECK (source IN ('subscription','protection_fee','commission')),
  source_ref_id uuid NOT NULL,           -- subscription_invoices.id / escrow_entries.id / follower_transactions.id
  base_amount   numeric(12,2) NOT NULL,  -- the platform's slice for this event (rupees)
  pct           numeric(5,2)  NOT NULL,
  amount        numeric(12,2) NOT NULL,  -- = round2(base_amount × pct / 100)
  payout_status text NOT NULL DEFAULT 'pending' CHECK (payout_status IN ('pending','paid')),
  paid_at       timestamptz NULL,
  created_at    timestamptz NOT NULL DEFAULT now()
);

-- idempotency: a webhook retry or cron re-run cannot double-accrue
CREATE UNIQUE INDEX IF NOT EXISTS uniq_referral_ledger_source_ref
  ON referral_ledger (source, source_ref_id);

CREATE INDEX IF NOT EXISTS idx_referral_ledger_referrer
  ON referral_ledger (referrer_type, referrer_id);

-- ── 4. influencers.referral_earned_total — reporting counter ────────────────
-- Referral payouts for influencer referrers land in existing wallet_balance;
-- this column is the cumulative "separate referral line" for reporting.
ALTER TABLE influencers
  ADD COLUMN IF NOT EXISTS referral_earned_total numeric(12,2) NOT NULL DEFAULT 0;

COMMIT;
